  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Randomized controlled trials were eligible for efficacy synthesis when they enrolled participants undergoing outpatient or office-based blind endometrial biopsy or endometrial sampling and reported pain, tolerability, additional analgesia, satisfaction, or adverse-event outcomes.",
      "reason": "The text explicitly specifies study design (RCTs), population (outpatient/office-based blind endometrial biopsy), and outcomes (pain, tolerability, etc.) used for eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "No restrictions were placed on publication year, language, country, indication for biopsy, menopausal status, or biopsy device, provided that the target procedure was blind endometrial biopsy or sampling and the relevant pain outcome was separable.",
      "reason": "The text explicitly states that no restrictions were placed on publication year, language, or country, addressing report characteristics."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "Of 208 reports or records sought for retrieval or eligibility clarification, 10 were not retrieved or had no public extractable results and 198 were assessed for eligibility.",
      "reason": "The text distinguishes between records excluded due to 'no usable pain or tolerability outcome' (screening) and those 'not retrieved or had no public extractable results' (retrieval), indicating a distinction between outcome measurement and reporting."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "To avoid mixing clinically different comparisons, we organized the evidence into three tiers. Tier 1 was the prespecified primary meta-analysis... Tier 2 comprised sensitivity analyses... Tier 3 comprised narrative or tabulated contextual evidence.",
      "reason": "The text explicitly specifies how studies were grouped for syntheses (Tier 1, 2, 3) and links them to the review objectives (primary meta-analysis, sensitivity, contextual)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Studies were excluded from the primary analysis when they centered on hysteroscopy-guided biopsy... because those settings differ in instrumentation, duration, uterine distension, cervical manipulation, and pain mechanisms.",
      "reason": "The text provides specific rationales for excluding certain study types, such as differences in instrumentation and pain mechanisms."
    }
  ],
  "confidence": 95
}

